package org.example.scheduler;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.example.service.CaptionService;
import org.example.service.ImageService;
import org.example.service.InstagramService;
import org.example.service.ScraperService;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.List;

@Slf4j
@Component
@RequiredArgsConstructor
public class PostScheduler {

    private static final Path HISTORY = Paths.get("history.txt");
    private static final Path HISTORY     = STORAGE_DIR.resolve("history.txt");

    private final ScraperService scraperService;
    private final ImageService imageService;
    private final InstagramService instagramService;
    private final CaptionService captionService;

    // Fires daily at 10:00 (server timezone): second 0, minute 0, hour 10, every day.
    @Scheduled(cron = "0 0 10 * * *")
    public void run() {
        try {
            log.info("Scheduler triggered");

            ArticleInfo article = scraperService.scrapeLatestArticle();

            if (article.getLink() == null) {
                log.warn("No article link found — skipping");
                return;
            }

            if (alreadyPosted(article.getLink())) {
                log.info("Already posted '{}' — skipping", article.getLink());
                return;
            }

            imageService.generateImage(article);
            imageService.generateStoryImage(article);
            instagramService.postImage(captionService.formatCaption(article.getContent()));
            instagramService.updateProfileWebsite(article.getLink());
            appendHistory(article.getLink());

            log.info("Done: {}", article.getLink());
        } catch (Exception e) {
            log.error("Scheduled post failed", e);
        }
    }

    private boolean alreadyPosted(String link) throws Exception {
        if (!Files.exists(HISTORY)) return false;
        List<String> lines = Files.readAllLines(HISTORY);
        if (lines.isEmpty()) return false;
        return lines.getLast().strip().equals(link.strip());
    }

    private void appendHistory(String link) throws Exception {
        Files.writeString(HISTORY, link + System.lineSeparator(),
                StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }
}

package org.example.scheduler;

import jakarta.annotation.PostConstruct;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.example.service.CaptionService;
import org.example.service.ImageService;
import org.example.service.InstagramService;
import org.example.service.ScraperService;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

@Slf4j
@Component
@RequiredArgsConstructor
public class PostScheduler {

    private static final Path STORAGE_DIR = Paths.get("storage");

    private final ScraperService   scraperService;
    private final ImageService     imageService;
    private final InstagramService instagramService;
    private final CaptionService   captionService;

    /** Guards against concurrent runs (startup-publisher vs cron firing simultaneously). */
    private final ReentrantLock runLock = new ReentrantLock();

    /** Ensures storage/ exists at startup so image files can be written. */
    @PostConstruct
    public void init() {
        try {
            Files.createDirectories(STORAGE_DIR);
            log.info("Storage directory ready: {}", STORAGE_DIR.toAbsolutePath());
        } catch (Exception e) {
            log.error("Failed to initialise storage directory", e);
        }
    }

    /** Triggered once immediately when the application is fully started — runs in background thread. */
    @EventListener(ApplicationReadyEvent.class)
    public void runOnStartup() {
        log.info("Application ready — running startup publication check");
        Thread thread = new Thread(() -> {
            try {
                run();
            } catch (Exception e) {
                log.error("Startup publication check failed", e);
            }
        }, "startup-publisher");
        thread.setDaemon(false);
        thread.start();
    }

    // Fires every 30 minutes to pick up new unpublished articles one by one
    @Scheduled(cron = "0 0/30 * * * *")
    public void run() {
        if (!runLock.tryLock()) {
            log.info("Scheduler skipped — another run is already in progress");
            return;
        }
        try {
            doRun();
        } finally {
            runLock.unlock();
        }
    }

    private void doRun() {
        try {
            log.info("Scheduler triggered");

            // Supabase query already filters posted_at=is.null — only unposted articles returned
            List<ArticleInfo> newArticles = scraperService.scrapeArticles(10);

            if (newArticles.isEmpty()) {
                log.info("No new articles found — skipping");
                return;
            }

            // Publish only 1 article per run to avoid OOM (Chromium memory pressure)
            ArticleInfo article = newArticles.get(0);
            log.info("Publishing 1 new article ({} unpublished total): {}",
                    newArticles.size(), article.getLink());
            try {
                imageService.generateImage(article);
                imageService.generateStoryImage(article);
                log.info("Generating caption for: {}", article.getTitle());
                String caption = captionService.formatCaption(article.getContent());
                log.info("Caption ready ({} chars), posting to Instagram...", caption.length());
                instagramService.postImage(caption);
                // Mark as posted in Supabase BEFORE anything else so a crash won't cause a double-post
                scraperService.markAsPosted(article.getSlug());
                log.info("Done: {}", article.getLink());
            } catch (Exception e) {
                log.error("Failed to post article '{}' — skipping", article.getLink(), e);
            }

        } catch (Exception e) {
            log.error("Scheduled post failed", e);
        }
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;
import java.util.Map;

@Slf4j
@Service
public class CaptionService {

    private static final String API_URL = "https://api.anthropic.com/v1/messages";
    private static final String MODEL   = "claude-haiku-4-5-20251001";

    private static final String CAPTION_SYSTEM = """
            Ты — редактор Instagram-аккаунта «The Vilnius» — русскоязычное городское медиа о Вильнюсе.
            Переформатируй текст новости в Instagram-подпись в профессиональном стиле «The Warsaw».

            Стиль:
            — В начале каждого абзаца ставь 1–2 релевантных эмодзи
            — Тон живой, вовлекающий, профессиональный
            — Между абзацами — пустая строка
            — Используй ПОЛНЫЙ текст новости — без сокращений, без ограничений по длине
            — Сохраняй все ключевые факты, цифры, имена и цитаты из исходника
            — Логичная структура: лид → детали → контекст/последствия

            Строго запрещено:
            — Хэштеги, ссылки, URL
            — Пометки «источник», «читать далее», подписи редакции
            — Любые пояснения от себя — только готовый caption
            """;

    private static final String KEY_PHRASE_SYSTEM = """
            Ты анализируешь русскоязычные заголовки новостей и выделяешь САМУЮ важную, шокирующую
            или интригующую часть, которую нужно подсветить жёлтым маркером в обложке.

            Правила:
            — Верни ТОЛЬКО подстроку из заголовка — без кавычек, без пояснений, без префиксов
            — Подстрока должна точно (буква в букву, регистр и пунктуация) встречаться в заголовке
            — От 1 до 4 идущих подряд слов, без обрывов
            — Выбирай конкретику (имя, цифру, событие, факт), а не служебные слова
              ("в Вильнюсе", "сегодня", "стало известно")
            — Если не уверен — выбери последние 2–3 содержательных слова заголовка

            Примеры:
            Заголовок: Волны краж в Вильнюсе: угнан BMW
            Ответ: угнан BMW

            Заголовок: Цены на жильё снова выросли
            Ответ: снова выросли

            Заголовок: Мэр объявил о массовом ремонте дорог
            Ответ: массовом ремонте дорог
            """;

    @Value("${anthropic.api-key}")
    private String apiKey;

    private final HttpClient http    = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();

    public String formatCaption(String rawContent) {
        if (rawContent == null || rawContent.isBlank()) return "";
        try {
            String result = callClaude(CAPTION_SYSTEM, rawContent, 4096);
            log.info("Caption formatted ({} chars)", result.length());
            return result;
        } catch (Exception e) {
            log.error("Caption LLM call failed — falling back to raw content", e);
            return rawContent;
        }
    }

    public String findKeyPhrase(String title) {
        if (title == null || title.isBlank()) return null;
        try {
            String raw = callClaude(KEY_PHRASE_SYSTEM, title, 64).strip();
            String phrase = raw.replaceAll("^[\"'«»\\s]+", "").replaceAll("[\"'«»\\s]+$", "");
            if (phrase.isBlank() || !title.contains(phrase)) {
                log.warn("Key phrase '{}' not a substring of title '{}' — using fallback", phrase, title);
                return null;
            }
            log.info("Key phrase: '{}'", phrase);
            return phrase;
        } catch (Exception e) {
            log.error("Key phrase LLM call failed — falling back to last words", e);
            return null;
        }
    }

    private String callClaude(String system, String userContent, int maxTokens) throws Exception {
        String systemJson = mapper.writeValueAsString(List.of(
                Map.of("type", "text",
                       "text", system,
                       "cache_control", Map.of("type", "ephemeral"))
        ));
        String userJson = mapper.writeValueAsString(userContent);

        String body = """
                {"model":"%s","max_tokens":%d,"system":%s,"messages":[{"role":"user","content":%s}]}
                """.formatted(MODEL, maxTokens, systemJson, userJson).strip();

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL))
                .header("x-api-key", apiKey)
                .header("anthropic-version", "2023-06-01")
                .header("anthropic-beta", "prompt-caching-2024-07-31")
                .header("content-type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();

        HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
        JsonNode json = mapper.readTree(response.body());

        if (json.has("error")) {
            throw new RuntimeException("Claude API error: " + response.body());
        }
        return json.path("content").get(0).path("text").asText();
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

@Slf4j
@Service
public class CaptionService {

    private static final String API_URL_TEMPLATE =
            "https://generativelanguage.googleapis.com/v1/models/gemini-2.5-flash-lite:generateContent?key=%s";

    private static final String CAPTION_SYSTEM = """
            Ты — редактор Instagram-аккаунта «The Vilnius» — русскоязычное городское медиа о Вильнюсе.
            Переформатируй текст новости в Instagram-подпись в профессиональном стиле «The Warsaw».

            Стиль:
            — В начале каждого абзаца ставь 1–2 релевантных эмодзи
            — Тон живой, вовлекающий, профессиональный
            — Между абзацами — пустая строка
            — Используй ПОЛНЫЙ текст новости — без сокращений, без ограничений по длине
            — Сохраняй все ключевые факты, цифры, имена и цитаты из исходника
            — Логичная структура: лид → детали → контекст/последствия

            Строго запрещено:
            — Хэштеги, ссылки, URL
            — Пометки «источник», «читать далее», подписи редакции
            — Любые пояснения от себя — только готовый caption
            """;

    private static final String KEY_PHRASE_SYSTEM = """
            Ты анализируешь русскоязычные заголовки новостей и выделяешь САМУЮ важную, шокирующую
            или интригующую часть, которую нужно подсветить жёлтым маркером в обложке.

            Правила:
            — Верни ТОЛЬКО подстроку из заголовка — без кавычек, без пояснений, без префиксов
            — Подстрока должна точно (буква в букву, регистр и пунктуация) встречаться в заголовке
            — От 1 до 4 идущих подряд слов, без обрывов
            — Выбирай конкретику (имя, цифру, событие, факт), а не служебные слова
              ("в Вильнюсе", "сегодня", "стало известно")
            — Если не уверен — выбери последние 2–3 содержательных слова заголовка

            Примеры:
            Заголовок: Волны краж в Вильнюсе: угнан BMW
            Ответ: угнан BMW

            Заголовок: Цены на жильё снова выросли
            Ответ: снова выросли

            Заголовок: Мэр объявил о массовом ремонте дорог
            Ответ: массовом ремонте дорог
            """;

    @Value("${gemini.api-key:}")
    private String apiKey;

    private final HttpClient    http   = HttpClient.newHttpClient();
    private final ObjectMapper  mapper = new ObjectMapper();

    @PostConstruct
    public void validateApiKey() {
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("⚠️  gemini.api-key is not set — caption/key-phrase generation will be skipped. " +
                     "Set the GEMINI_API_KEY environment variable to enable AI features.");
        } else {
            log.info("Gemini API configured (gemini-2.5-flash-lite)");
        }
    }

    public String formatCaption(String rawContent) {
        if (rawContent == null || rawContent.isBlank()) return "";
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("Gemini API key not set — returning raw content as caption");
            return truncate(rawContent);
        }
        try {
            String result = callGemini(CAPTION_SYSTEM, rawContent, 4096);
            result = truncate(result);
            log.info("Caption formatted ({} chars)", result.length());
            return result;
        } catch (Exception e) {
            log.error("Caption Gemini call failed — falling back to raw content", e);
            return truncate(rawContent);
        }
    }

    /** Hard-trims caption to Instagram's 2200-char limit, cutting at the last newline before the limit. */
    private static String truncate(String text) {
        if (text == null || text.length() <= INSTAGRAM_MAX_CAPTION) return text;
        String cut = text.substring(0, INSTAGRAM_MAX_CAPTION);
        int lastNl = cut.lastIndexOf('\n');
        return (lastNl > INSTAGRAM_MAX_CAPTION / 2 ? cut.substring(0, lastNl) : cut).stripTrailing();
    }

    public String findKeyPhrase(String title) {
        if (title == null || title.isBlank()) return null;
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("Gemini API key not set — skipping key-phrase detection");
            return null;
        }
        try {
            String raw    = callGemini(KEY_PHRASE_SYSTEM, title, 64).strip();
            String phrase = raw.replaceAll("^[\"'«»\\s]+", "").replaceAll("[\"'«»\\s]+$", "");
            if (phrase.isBlank() || !title.contains(phrase)) {
                log.warn("Key phrase '{}' not a substring of title '{}' — using fallback", phrase, title);
                return null;
            }
            log.info("Key phrase: '{}'", phrase);
            return phrase;
        } catch (Exception e) {
            log.error("Key phrase Gemini call failed — falling back to last words", e);
            return null;
        }
    }

    /**
     * Calls the Gemini REST API (no SDK needed — plain HTTP).
     * Endpoint: POST https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=...
     */
    private String callGemini(String systemPrompt, String userContent, int maxOutputTokens) throws Exception {
        // Combine system prompt + user content into a single user message (v1 doesn't support systemInstruction)
        String combinedText = systemPrompt.strip() + "\n\n" + userContent;

        String body = mapper.writeValueAsString(java.util.Map.of(
                "contents", java.util.List.of(java.util.Map.of(
                        "role", "user",
                        "parts", java.util.List.of(java.util.Map.of("text", combinedText))
                )),
                "generationConfig", java.util.Map.of(
                        "maxOutputTokens", maxOutputTokens,
                        "temperature", 0.7
                )
        ));

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL_TEMPLATE.formatted(apiKey)))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();

        HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
        JsonNode json = mapper.readTree(response.body());

        // Surface API errors clearly
        if (json.has("error")) {
            String errorMsg = json.path("error").path("message").asText(response.body());
            throw new RuntimeException("Gemini API error (%d): %s".formatted(response.statusCode(), errorMsg));
        }

        return json.path("candidates").get(0)
                   .path("content").path("parts").get(0)
                   .path("text").asText();
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Persists the set of already-posted article slugs in Supabase Storage.
 * No SQL / schema changes required — uses the Storage REST API with the service-role key.
 *
 * Bucket: "instagram-bot"
 * File:   "posted_slugs.json"  ← JSON array of slug strings
 */
@Slf4j
@Service
public class HistoryService {

    @Value("${supabase.url}")
    private String supabaseUrl;

    @Value("${supabase.service-key}")
    private String serviceKey;

    private static final String BUCKET    = "instagram-bot";
    private static final String FILE_PATH = "posted_slugs.json";

    private final HttpClient   http   = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(15))
            .build();
    private final ObjectMapper mapper = new ObjectMapper();

    /** In-memory cache — loaded from Supabase Storage on startup. */
    private final Set<String> posted = Collections.synchronizedSet(new HashSet<>());

    @PostConstruct
    public void init() {
        ensureBucketExists();
        loadFromStorage();
    }

    /** Returns true if this slug was already published to Instagram. */
    public boolean isPosted(String slug) {
        return slug != null && posted.contains(slug);
    }

    /** Records the slug as posted in memory AND persists to Supabase Storage. */
    public void markAsPosted(String slug) {
        if (slug == null || slug.isBlank()) return;
        posted.add(slug);
        saveToStorage();
        log.info("Marked as posted: slug='{}'  (total history: {})", slug, posted.size());
    }

    // ────────────────────────────────────────────────────────────────────────────
    // Private helpers
    // ────────────────────────────────────────────────────────────────────────────

    private void ensureBucketExists() {
        try {
            String url  = supabaseUrl + "/storage/v1/bucket";
            String body = "{\"id\":\"" + BUCKET + "\",\"name\":\"" + BUCKET + "\",\"public\":false}";

            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .timeout(Duration.ofSeconds(10))
                    .header("apikey", serviceKey)
                    .header("Authorization", "Bearer " + serviceKey)
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(body))
                    .build();

            HttpResponse<String> res = http.send(req, HttpResponse.BodyHandlers.ofString());
            if (res.statusCode() == 200 || res.statusCode() == 201) {
                log.info("Supabase Storage bucket '{}' created", BUCKET);
            } else {
                // 409 = already exists — that's fine
                log.debug("Bucket '{}' check: status={}", BUCKET, res.statusCode());
            }
        } catch (Exception e) {
            log.warn("Could not ensure storage bucket '{}' exists: {}", BUCKET, e.getMessage());
        }
    }

    private void loadFromStorage() {
        try {
            String url = supabaseUrl + "/storage/v1/object/" + BUCKET + "/" + FILE_PATH;

            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .timeout(Duration.ofSeconds(10))
                    .header("apikey", serviceKey)
                    .header("Authorization", "Bearer " + serviceKey)
                    .GET()
                    .build();

            HttpResponse<String> res = http.send(req, HttpResponse.BodyHandlers.ofString());

            if (res.statusCode() == 200) {
                String[] slugs = mapper.readValue(res.body(), String[].class);
                for (String s : slugs) posted.add(s);
                log.info("Loaded {} posted slugs from Supabase Storage", posted.size());
            } else if (res.statusCode() == 400 || res.statusCode() == 404) {
                log.info("No history file yet in Supabase Storage — starting fresh");
            } else {
                log.warn("Unexpected status loading history: {} — {}", res.statusCode(), res.body());
            }
        } catch (Exception e) {
            log.warn("Could not load history from Supabase Storage: {}", e.getMessage());
        }
    }

    private void saveToStorage() {
        try {
            String url  = supabaseUrl + "/storage/v1/object/" + BUCKET + "/" + FILE_PATH;
            String body = mapper.writeValueAsString(posted);

            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .timeout(Duration.ofSeconds(10))
                    .header("apikey", serviceKey)
                    .header("Authorization", "Bearer " + serviceKey)
                    .header("Content-Type", "application/json")
                    .header("x-upsert", "true")   // create-or-replace
                    .POST(HttpRequest.BodyPublishers.ofString(body))
                    .build();

            HttpResponse<String> res = http.send(req, HttpResponse.BodyHandlers.ofString());
            if (res.statusCode() >= 200 && res.statusCode() < 300) {
                log.info("History saved to Supabase Storage ({} slugs total)", posted.size());
            } else {
                log.warn("Failed to save history to Storage: status={}, body={}", res.statusCode(), res.body());
            }
        } catch (Exception e) {
            log.warn("Could not save history to Supabase Storage: {}", e.getMessage());
        }
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;

@Slf4j
@Service
public class InstagramService {

    private static final String GRAPH_API = "https://graph.facebook.com/v19.0";

    @Value("${instagram.user.id}")
    private String userId;

    @Value("${instagram.access.token}")
    private String accessToken;

    @Value("${app.public-url}")
    private String publicUrl;

    private final HttpClient http = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();

    public void postImage(String caption) throws Exception {
        String feedImageUrl = publicUrl.stripTrailing() + "/images/" + ImageService.OUTPUT_FILENAME;
        log.info("Posting image from URL: {}", feedImageUrl);

        String creationId = createMediaContainer(feedImageUrl, caption);
        log.info("Media container created: {}", creationId);

        awaitContainerReady(creationId);
        publishMedia(creationId);
        log.info("Published to feed successfully");

        // Story upload with dedicated 9:16 image — failure is non-fatal
        try {
            String storyImageUrl = publicUrl.stripTrailing() + "/images/" + ImageService.STORY_FILENAME;
            postStory(storyImageUrl);
        } catch (Exception e) {
            log.error("Story upload failed (non-fatal): {}", e.getMessage());
        }
    }

    public void postStoryOnly() throws Exception {
        String storyImageUrl = publicUrl.stripTrailing() + "/images/" + ImageService.STORY_FILENAME;
        log.info("Posting story-only from URL: {}", storyImageUrl);
        postStory(storyImageUrl);
        log.info("Story-only post done");
    }

    // Attempts to update the IG Business Profile "website" field via Graph API.
    // Not documented as writable on FB-Page-linked accounts, so this is best-effort:
    // we log Meta's full response and never throw. Caller decides whether to retry/fallback.
    public void updateProfileWebsite(String articleUrl) {
        if (articleUrl == null || articleUrl.isBlank()) {
            log.warn("Profile website update skipped — empty URL");
            return;
        }
        try {
            String body = "website=" + encode(articleUrl)
                    + "&access_token=" + encode(accessToken);
            HttpResponse<String> response = post(GRAPH_API + "/" + userId, body);
            int status = response.statusCode();
            String snippet = response.body() == null ? "" : response.body();
            if (status >= 200 && status < 300 && !snippet.contains("\"error\"")) {
                log.info("Profile website updated to {} (status={}, body={})", articleUrl, status, snippet);
            } else {
                log.warn("Profile website update rejected by Meta (status={}, body={}). " +
                        "This endpoint is not generally writable on FB-Page-linked tokens — " +
                        "consider the /latest redirect fallback.", status, snippet);
            }
        } catch (Exception e) {
            log.warn("Profile website update failed (non-fatal): {}", e.getMessage());
        }
    }

    private void postStory(String imageUrl) throws Exception {
        log.info("Posting story...");
        String body = "image_url=" + encode(imageUrl)
                + "&media_type=STORIES"
                + "&access_token=" + encode(accessToken);

        HttpResponse<String> response = post(GRAPH_API + "/" + userId + "/media", body);
        log.debug("Create story container response: {}", response.body());

        JsonNode json = mapper.readTree(response.body());
        requireField(json, "id", response.body());
        String storyContainerId = json.get("id").asText();

        awaitContainerReady(storyContainerId);

        String publishBody = "creation_id=" + encode(storyContainerId)
                + "&access_token=" + encode(accessToken);
        HttpResponse<String> publishResponse = post(GRAPH_API + "/" + userId + "/media_publish", publishBody);
        JsonNode publishJson = mapper.readTree(publishResponse.body());
        requireField(publishJson, "id", publishResponse.body());
        log.info("Story published successfully");
    }

    private String createMediaContainer(String imageUrl, String caption) throws Exception {
        String body = "image_url=" + encode(imageUrl)
                + "&caption=" + encode(caption)
                + "&access_token=" + encode(accessToken);

        HttpResponse<String> response = post(GRAPH_API + "/" + userId + "/media", body);
        log.debug("Create media response: {}", response.body());

        JsonNode json = mapper.readTree(response.body());
        requireField(json, "id", response.body());
        return json.get("id").asText();
    }

    private void awaitContainerReady(String creationId) throws Exception {
        String url = GRAPH_API + "/" + creationId
                + "?fields=status_code&access_token=" + encode(accessToken);
        HttpRequest request = HttpRequest.newBuilder().uri(URI.create(url)).GET().build();

        int maxAttempts = 20;
        for (int i = 1; i <= maxAttempts; i++) {
            Thread.sleep(3_000);
            HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
            JsonNode json = mapper.readTree(response.body());
            String statusCode = json.path("status_code").asText("");
            log.info("Container status [{}/{}]: {}", i, maxAttempts, statusCode);

            switch (statusCode) {
                case "FINISHED" -> { return; }
                case "ERROR", "EXPIRED" ->
                    throw new RuntimeException("Container not publishable, status=" + statusCode
                            + " body=" + response.body());
                // IN_PROGRESS or empty → keep polling
            }
        }
        throw new RuntimeException("Container still not ready after " + maxAttempts + " attempts");
    }

    private void publishMedia(String creationId) throws Exception {
        String body = "creation_id=" + encode(creationId)
                + "&access_token=" + encode(accessToken);

        HttpResponse<String> response = post(GRAPH_API + "/" + userId + "/media_publish", body);
        log.debug("Publish response: {}", response.body());

        JsonNode json = mapper.readTree(response.body());
        requireField(json, "id", response.body());
    }

    private HttpResponse<String> post(String url, String formBody) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString(formBody))
                .build();
        return http.send(request, HttpResponse.BodyHandlers.ofString());
    }

    private static void requireField(JsonNode json, String field, String rawBody) {
        if (!json.has(field)) {
            throw new RuntimeException("Missing '" + field + "' in response: " + rawBody);
        }
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8);
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;

@Slf4j
@Service
public class InstagramService {

    private static final String GRAPH_API = "https://graph.facebook.com/v19.0";

    @Value("${instagram.user.id}")
    private String userId;

    @Value("${instagram.access.token}")
    private String accessToken;

    @Value("${app.public-url}")
    private String publicUrl;

    private final HttpClient http = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();

    public void postImage(String caption) throws Exception {
        String feedImageUrl = publicUrl.stripTrailing() + "/images/" + ImageService.OUTPUT_FILENAME;
        log.info("Posting image from URL: {}", feedImageUrl);

        String creationId = createMediaContainer(feedImageUrl, caption);
        log.info("Media container created: {}", creationId);

        awaitContainerReady(creationId, 20); // 20 attempts × 3s = 60s max for feed
        publishMedia(creationId);
        log.info("Published to feed successfully");

        // Story upload with dedicated 9:16 image — failure is non-fatal
        try {
            String storyImageUrl = publicUrl.stripTrailing() + "/images/" + ImageService.STORY_FILENAME;
            postStory(storyImageUrl);
        } catch (Exception e) {
            log.error("Story upload failed (non-fatal): {}", e.getMessage());
        }
    }

    public void postStoryOnly() throws Exception {
        String storyImageUrl = publicUrl.stripTrailing() + "/images/" + ImageService.STORY_FILENAME;
        log.info("Posting story-only from URL: {}", storyImageUrl);
        postStory(storyImageUrl);
        log.info("Story-only post done");
    }

    // Attempts to update the IG Business Profile "website" field via Graph API.
    // Not documented as writable on FB-Page-linked accounts, so this is best-effort:
    // we log Meta's full response and never throw. Caller decides whether to retry/fallback.
    public void updateProfileWebsite(String articleUrl) {
        if (articleUrl == null || articleUrl.isBlank()) {
            log.warn("Profile website update skipped — empty URL");
            return;
        }
        try {
            String body = "website=" + encode(articleUrl)
                    + "&access_token=" + encode(accessToken);
            HttpResponse<String> response = post(GRAPH_API + "/" + userId, body);
            int status = response.statusCode();
            String snippet = response.body() == null ? "" : response.body();
            if (status >= 200 && status < 300 && !snippet.contains("\"error\"")) {
                log.info("Profile website updated to {} (status={}, body={})", articleUrl, status, snippet);
            } else {
                log.warn("Profile website update rejected by Meta (status={}, body={}). " +
                        "This endpoint is not generally writable on FB-Page-linked tokens — " +
                        "consider the /latest redirect fallback.", status, snippet);
            }
        } catch (Exception e) {
            log.warn("Profile website update failed (non-fatal): {}", e.getMessage());
        }
    }

    private void postStory(String imageUrl) throws Exception {
        log.info("Posting story...");
        String body = "image_url=" + encode(imageUrl)
                + "&media_type=STORIES"
                + "&access_token=" + encode(accessToken);

        HttpResponse<String> response = post(GRAPH_API + "/" + userId + "/media", body);
        log.debug("Create story container response: {}", response.body());

        JsonNode json = mapper.readTree(response.body());
        requireField(json, "id", response.body());
        String storyContainerId = json.get("id").asText();

        awaitContainerReady(storyContainerId, 10); // 10 attempts × 3s = 30s max for story

        String publishBody = "creation_id=" + encode(storyContainerId)
                + "&access_token=" + encode(accessToken);
        HttpResponse<String> publishResponse = post(GRAPH_API + "/" + userId + "/media_publish", publishBody);
        JsonNode publishJson = mapper.readTree(publishResponse.body());
        requireField(publishJson, "id", publishResponse.body());
        log.info("Story published successfully");
    }

    private String createMediaContainer(String imageUrl, String caption) throws Exception {
        String body = "image_url=" + encode(imageUrl)
                + "&caption=" + encode(caption)
                + "&access_token=" + encode(accessToken);

        HttpResponse<String> response = post(GRAPH_API + "/" + userId + "/media", body);
        log.debug("Create media response: {}", response.body());

        JsonNode json = mapper.readTree(response.body());
        requireField(json, "id", response.body());
        return json.get("id").asText();
    }

    private void awaitContainerReady(String creationId, int maxAttempts) throws Exception {
        String url = GRAPH_API + "/" + creationId
                + "?fields=status_code&access_token=" + encode(accessToken);
        HttpRequest request = HttpRequest.newBuilder().uri(URI.create(url)).GET().build();

        for (int i = 1; i <= maxAttempts; i++) {
            Thread.sleep(3_000);
            HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
            JsonNode json = mapper.readTree(response.body());
            String statusCode = json.path("status_code").asText("");
            log.info("Container status [{}/{}]: {}", i, maxAttempts, statusCode);

            switch (statusCode) {
                case "FINISHED" -> { return; }
                case "ERROR", "EXPIRED" ->
                    throw new RuntimeException("Container not publishable, status=" + statusCode
                            + " body=" + response.body());
                // IN_PROGRESS or empty → keep polling
            }
        }
        throw new RuntimeException("Container still not ready after " + maxAttempts + " attempts");
    }

    private void publishMedia(String creationId) throws Exception {
        String body = "creation_id=" + encode(creationId)
                + "&access_token=" + encode(accessToken);

        HttpResponse<String> response = post(GRAPH_API + "/" + userId + "/media_publish", body);
        log.debug("Publish response: {}", response.body());

        JsonNode json = mapper.readTree(response.body());
        requireField(json, "id", response.body());
    }

    private HttpResponse<String> post(String url, String formBody) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString(formBody))
                .build();
        return http.send(request, HttpResponse.BodyHandlers.ofString());
    }

    private static void requireField(JsonNode json, String field, String rawBody) {
        if (!json.has(field)) {
            throw new RuntimeException("Missing '" + field + "' in response: " + rawBody);
        }
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8);
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Slf4j
@Service
public class ScraperService {

    private static final String SITE_BASE = "https://thevilnius.lt";

    @Value("${supabase.url}")
    private String supabaseUrl;

    @Value("${supabase.anon-key}")
    private String supabaseAnonKey;

    private final RestTemplate restTemplate = new RestTemplate();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public ArticleInfo scrapeLatestArticle() throws Exception {
        // "Последние новости" section → category=news, ordered by publish date
        String url = supabaseUrl + "/rest/v1/articles"
                + "?order=published_at.desc&limit=1&status=eq.published&category=eq.news"
                + "&select=title,slug,image_url,content";

        HttpHeaders headers = new HttpHeaders();
        headers.set("apikey", supabaseAnonKey);
        headers.set("Authorization", "Bearer " + supabaseAnonKey);

        ResponseEntity<String> response = restTemplate.exchange(
                url, HttpMethod.GET, new HttpEntity<>(headers), String.class);

        JsonNode root = objectMapper.readTree(response.getBody());
        if (!root.isArray() || root.isEmpty()) {
            log.warn("Supabase returned no news articles");
            return new ArticleInfo();
        }

        JsonNode node = root.get(0);
        ArticleInfo info = new ArticleInfo();
        info.setTitle(node.path("title").asText(null));
        info.setLink(SITE_BASE + "/articles/" + node.path("slug").asText());
        info.setImageUrl(node.path("image_url").asText(null));
        info.setContent(node.path("content").asText(null));

        log.info("Scraped news: title='{}', link='{}'", info.getTitle(), info.getLink());
        return info;
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;

@Slf4j
@Service
public class ScraperService {

    private static final String SITE_BASE = "https://thevilnius.lt";

    @Value("${supabase.url}")
    private String supabaseUrl;

    @Value("${supabase.anon-key}")
    private String supabaseAnonKey;

    private final HttpClient httpClient = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(15))
            .build();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public ArticleInfo scrapeLatestArticle() throws Exception {
        List<ArticleInfo> articles = scrapeArticles(1);
        return articles.isEmpty() ? new ArticleInfo() : articles.get(0);
    }

    /**
     * Fetches the {@code limit} most-recently-published news articles from Supabase.
     * Deduplication (already-posted filtering) is handled externally by HistoryService.
     */
    public List<ArticleInfo> scrapeArticles(int limit) throws Exception {
        String url = supabaseUrl + "/rest/v1/articles"
                + "?order=published_at.desc&limit=" + limit
                + "&status=eq.published&category=eq.news"
                + "&select=title,slug,image_url,content";

        log.info("Fetching articles from Supabase: {}", url);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .timeout(Duration.ofSeconds(30))
                .header("apikey", supabaseAnonKey)
                .header("Authorization", "Bearer " + supabaseAnonKey)
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        log.info("Supabase response status: {}", response.statusCode());

        if (response.statusCode() != 200) {
            log.error("Supabase returned error: status={}, body={}", response.statusCode(), response.body());
            return List.of();
        }

        JsonNode root = objectMapper.readTree(response.body());
        if (!root.isArray() || root.isEmpty()) {
            log.warn("Supabase returned no news articles");
            return List.of();
        }

        List<ArticleInfo> results = new ArrayList<>();
        for (JsonNode node : root) {
            ArticleInfo info = new ArticleInfo();
            info.setTitle(node.path("title").asText(null));
            info.setSlug(node.path("slug").asText(null));
            info.setLink(SITE_BASE + "/articles/" + node.path("slug").asText());
            info.setImageUrl(node.path("image_url").asText(null));
            info.setContent(node.path("content").asText(null));
            log.info("Scraped news: title='{}', link='{}'", info.getTitle(), info.getLink());
            results.add(info);
        }
        return results;
    }
}
